{"implementation":"def solve(case):
    refinement = case["refinement"]
    members = {}
    for v, g in refinement.items():
        members.setdefault(g, []).append(v)
    edge_weight = {}
    for u, v, w in case["edges"]:
        gu = refinement[u]
        gv = refinement[v]
        if gu != gv:
            key = tuple(sorted((gu, gv)))
            edge_weight[key] = edge_weight.get(key, 0) + w
    aggregate_edges = []
    for (g1, g2), total in sorted(edge_weight.items()):
        aggregate_edges.append([g1, g2, total])
    return {"aggregate_edges": aggregate_edges, "members": members}"}
